// ─── STATE ───
let cart = JSON.parse(localStorage.getItem('seira_cart') || '[]');
let wishlist = JSON.parse(localStorage.getItem('seira_wishlist') || '[]');
let filters = { category: 'All', gender: 'All', material: 'All', maxPrice: 500000 };
let sortOrder = 'default';
let searchQuery = '';
let darkMode = false;

// ─── INIT ───
window.onload = () => {
  setTimeout(() => {
    document.getElementById('loader').style.opacity = '0';
    setTimeout(() => document.getElementById('loader').style.display = 'none', 600);
  }, 1800);
  createParticles();
  renderFeatured();
  renderShop();
  updateCartCount();
};

function createParticles() {
  const container = document.getElementById('particles');
  for (let i = 0; i < 40; i++) {
    const p = document.createElement('div');
    p.className = 'particle';
    p.style.cssText = `
      left: ${Math.random()*100}%;
      width: ${Math.random()*3+1}px;
      height: ${Math.random()*3+1}px;
      animation-duration: ${Math.random()*8+5}s;
      animation-delay: ${Math.random()*10}s;
    `;
    container.appendChild(p);
  }
}

// ─── PAGES ───
function showPage(name) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.getElementById('page-'+name).classList.add('active');
  window.scrollTo(0, 0);
  if (name === 'cart') renderCartPage();
  if (name === 'wishlist') renderWishlist();
  if (name === 'shop') renderShop();
}

// ─── PRODUCT CARD HTML ───
function cardHTML(p, showRemove = false) {
  const isWished = wishlist.includes(p.id);
  return `
    <div class="product-card" id="card-${p.id}">
      ${p.badge ? `<div style="position:absolute;top:.7rem;left:.7rem;background:var(--gold);color:var(--black);font-size:.6rem;padding:.2rem .6rem;font-weight:700;letter-spacing:.1em;z-index:1;border-radius:2px">${p.badge}</div>` : ''}
      <div class="product-img" onclick="openModal(${p.id})">
        <img src="${p.image}" alt="${p.name}" loading="lazy">
        <button class="wish-btn ${isWished?'active':''}" onclick="event.stopPropagation();toggleWishlist(${p.id})" id="wish-${p.id}">♥</button>
      </div>
      <div class="product-info">
        <h4>${p.name}</h4>
        <div class="stars">${'⭐'.repeat(Math.floor(p.rating))}</div>
        <div class="price">₹${p.price.toLocaleString('en-IN')}</div>
        ${showRemove
          ? `<button class="add-cart-btn" style="background:#e74c3c;border-color:#e74c3c;color:#fff" onclick="toggleWishlist(${p.id})">Remove</button>`
          : `<button class="add-cart-btn" onclick="addToCart(${p.id})">Add to Cart</button>`}
      </div>
    </div>`;
}

// ─── FEATURED ───
function renderFeatured() {
  const featured = products.filter(p => p.rating === 5).slice(0, 8);
  document.getElementById('featuredGrid').innerHTML = featured.map(p => cardHTML(p)).join('');
}

// ─── SHOP ───
function renderShop() {
  let filtered = products.filter(p => {
    const catOk = filters.category === 'All' || p.category === filters.category;
    const genOk = filters.gender === 'All' || p.gender === filters.gender;
    const matOk = filters.material === 'All' || p.material === filters.material;
    const priceOk = p.price <= filters.maxPrice;
    const searchOk = !searchQuery || p.name.toLowerCase().includes(searchQuery.toLowerCase()) || p.category.toLowerCase().includes(searchQuery.toLowerCase());
    return catOk && genOk && matOk && priceOk && searchOk;
  });
  if (sortOrder === 'low') filtered.sort((a,b) => a.price - b.price);
  else if (sortOrder === 'high') filtered.sort((a,b) => b.price - a.price);
  else if (sortOrder === 'rating') filtered.sort((a,b) => b.rating - a.rating);
  document.getElementById('productCount').textContent = `Showing ${filtered.length} products`;
  document.getElementById('shopGrid').innerHTML = filtered.map(p => cardHTML(p)).join('');
}

function filterShop(category) {
  filters.category = category;
  document.querySelectorAll('.filter-chip').forEach(chip => {
    chip.classList.remove("active") 
   if(chip.textContent === category){
      chip.classList.add("active")
    }
  })

  renderShop()
}
function setCatFilter(el, val) {
  filters.category = val;
  document.querySelectorAll('#catChips .filter-chip').forEach(c => c.classList.remove('active'));
  el.classList.add('active');
  renderShop();
}
function setGenderFilter(el, val) {
  filters.gender = val;
  el.closest('.filter-chips').querySelectorAll('.filter-chip').forEach(c => c.classList.remove('active'));
  el.classList.add('active');
  renderShop();
}
function setPriceFilter(val) {
  filters.maxPrice = parseInt(val);
  document.getElementById('priceVal').textContent = '₹' + parseInt(val).toLocaleString('en-IN');
  renderShop();
}
function setMaterialFilter(val) {
  filters.material = val;
  renderShop();
}
function sortProducts(val) {
  sortOrder = val;
  renderShop();
}
function handleSearch(val) {
  searchQuery = val;
  if (val.length > 0) showPage('shop');
  else renderShop();
  renderShop();
}

// ─── CART ───
function addToCart(id) {
  const existing = cart.find(i => i.id === id);
  if (existing) existing.qty++;
  else cart.push({ id, qty: 1 });
  saveCart();
  updateCartCount();
  renderDrawer();
  showToast('Added to cart! 🛍');
}
function removeFromCart(id) {
  cart = cart.filter(i => i.id !== id);
  saveCart();
  updateCartCount();
  renderCartPage();
  renderDrawer();
}
function updateQty(id, delta) {
  const item = cart.find(i => i.id === id);
  if (!item) return;
  item.qty += delta;
  if (item.qty <= 0) return removeFromCart(id);
  saveCart();
  renderCartPage();
  renderDrawer();
}
function saveCart() {
  localStorage.setItem('seira_cart', JSON.stringify(cart));
}
function updateCartCount() {
  const total = cart.reduce((s,i) => s + i.qty, 0);
  document.getElementById('cartCount').textContent = total;
}
function renderCartPage() {
  const container = document.getElementById('cartContent');
  if (cart.length === 0) {
    container.innerHTML = `<div class="cart-empty"><div class="icon">🛍</div><p>Your cart is empty</p><button class="btn-gold" onclick="showPage('shop')">Shop Now</button></div>`;
    return;
  }
  const total = cart.reduce((s,i) => {
    const p = products.find(x => x.id === i.id);
    return s + (p ? p.price * i.qty : 0);
  }, 0);
  container.innerHTML = `
    <div class="cart-layout">
      <div class="cart-items">
        ${cart.map(i => {
          const p = products.find(x => x.id === i.id);
          if (!p) return '';
          return `<div class="cart-item">
            <img src="${p.image}" alt="${p.name}">
            <div class="cart-item-info">
              <h4>${p.name}</h4>
              <div class="price">₹${(p.price*i.qty).toLocaleString('en-IN')}</div>
              <div class="qty-control">
                <button class="qty-btn" onclick="updateQty(${p.id},-1)">−</button>
                <span class="qty-num">${i.qty}</span>
                <button class="qty-btn" onclick="updateQty(${p.id},1)">+</button>
              </div>
            </div>
            <button class="remove-btn" onclick="removeFromCart(${p.id})">Remove</button>
          </div>`;
        }).join('')}
      </div>
      <div class="cart-summary">
        <h3>Order Summary</h3>
        <div class="summary-row"><span>Subtotal</span><span>₹${total.toLocaleString('en-IN')}</span></div>
        <div class="summary-row"><span>Shipping</span><span style="color:#4caf50">Free</span></div>
        <div class="summary-row"><span>GST (3%)</span><span>₹${Math.round(total*0.03).toLocaleString('en-IN')}</span></div>
        <div class="summary-row total"><span>Total</span><span style="color:var(--gold)">₹${Math.round(total*1.03).toLocaleString('en-IN')}</span></div>
        <button class="btn-gold" style="width:100%;margin-top:1.5rem" onclick="checkout()">Proceed to Checkout</button>
      </div>
    </div>`;
}
function renderDrawer() {
  const container = document.getElementById('drawerItems');
  if (cart.length === 0) {
    container.innerHTML = '<p style="color:var(--gray);font-size:.8rem;text-align:center;margin-top:2rem">Your cart is empty</p>';
    document.getElementById('drawerTotal').textContent = '₹0';
    return;
  }
  const total = cart.reduce((s,i) => {
    const p = products.find(x => x.id === i.id);
    return s + (p ? p.price * i.qty : 0);
  }, 0);
  container.innerHTML = cart.map(i => {
    const p = products.find(x => x.id === i.id);
    if (!p) return '';
    return `<div class="drawer-item">
      <img src="${p.image}" alt="${p.name}">
      <div class="drawer-item-info">
        <h5>${p.name}</h5>
        <span>₹${p.price.toLocaleString('en-IN')} × ${i.qty}</span>
      </div>
    </div>`;
  }).join('');
  document.getElementById('drawerTotal').textContent = '₹' + total.toLocaleString('en-IN');
}
function toggleCart() {
  renderDrawer();
  document.getElementById('cartDrawer').classList.toggle('open');
  document.getElementById('overlayBg').classList.toggle('show');
}
function closeCart() {
  document.getElementById('cartDrawer').classList.remove('open');
  document.getElementById('overlayBg').classList.remove('show');
}
function checkout() {
  cart = []; saveCart(); updateCartCount(); renderDrawer(); closeCart();
  if (document.getElementById('page-cart').classList.contains('active')) renderCartPage();
  showToast('🎉 Order placed successfully! Thank you for shopping with SEIRA.');
}

// ─── WISHLIST ───
function toggleWishlist(id) {
  if (wishlist.includes(id)) wishlist = wishlist.filter(i => i !== id);
  else { wishlist.push(id); showToast('Added to wishlist ♥'); }
  localStorage.setItem('seira_wishlist', JSON.stringify(wishlist));
  const btn = document.getElementById('wish-'+id);
  if (btn) btn.classList.toggle('active', wishlist.includes(id));
  if (document.getElementById('page-wishlist').classList.contains('active')) renderWishlist();
}
function renderWishlist() {
  const grid = document.getElementById('wishlistGrid');
  const empty = document.getElementById('wishlistEmpty');
  if (wishlist.length === 0) {
    grid.innerHTML = '';
    empty.style.display = 'block';
    return;
  }
  empty.style.display = 'none';
  const items = products.filter(p => wishlist.includes(p.id));
  grid.innerHTML = items.map(p => cardHTML(p, true)).join('');
}

// ─── PRODUCT MODAL ───
function openModal(id) {
  const p = products.find(x => x.id === id);
  if (!p) return;
  document.getElementById('modalInner').innerHTML = `
    <button class="modal-close" onclick="closeModal()">✕</button>
    <div class="modal-img"><img src="${p.image}" alt="${p.name}"></div>
    <div class="modal-info">
      <h2>${p.name}</h2>
      <div class="stars">${'⭐'.repeat(Math.floor(p.rating))} (${p.rating}.0)</div>
      <div class="modal-price">₹${p.price.toLocaleString('en-IN')}</div>
      <p>${p.desc}</p>
      <div class="modal-meta">
        <span><strong>Category:</strong> ${p.category}</span>
        <span><strong>Material:</strong> ${p.material}</span>
        <span><strong>For:</strong> ${p.gender}</span>
        <span><strong>Availability:</strong> <span style="color:#4caf50">✓ In Stock</span></span>
      </div>
      <div class="modal-btns">
        <button class="btn-gold" onclick="addToCart(${p.id});closeModal()">Add to Cart</button>
        <button class="btn-gold" onclick="addToCart(${p.id});closeModal();checkout()">Buy Now</button>
        <button class="btn-outline" style="color:var(--gold);border:1px solid var(--gold);padding:.85rem;font-family:'Montserrat',sans-serif;font-size:.75rem;letter-spacing:.2em;text-transform:uppercase;cursor:pointer;background:transparent;transition:all .3s" onclick="toggleWishlist(${p.id});closeModal()">♥ Add to Wishlist</button>
      </div>
    </div>`;
  document.getElementById('productModal').classList.add('open');
}
function closeModal() {
  document.getElementById('productModal').classList.remove('open');
}

// ─── LOGIN ───
function switchTab(tab) {
  document.querySelectorAll('.auth-tab').forEach((t,i) => t.classList.toggle('active', (i===0&&tab==='login')||(i===1&&tab==='signup')));
  document.getElementById('form-login').classList.toggle('active', tab === 'login');
  document.getElementById('form-signup').classList.toggle('active', tab === 'signup');
}
async function handleLogin(event){
  event.preventDefault()
  const email = document.getElementById("loginEmail").value
  const password = document.getElementById("loginPass").value
  try{

     const response = await fetch("http://localhost:5000/api/auth/login",{

        method:"POST",
        headers:{
           "Content-Type":"application/json"
        },
        body:JSON.stringify({
           email,
           password
        })
     })

     const data = await response.json()
     if(data.token){
        localStorage.setItem("token",data.token)
        showToast("Login successful")
        setTimeout(()=>{
           showPage("home")
        },1000)
     }else{
        showToast(data.message)
     }
  }catch(err){
     showToast("Server error")
  }
}

async function handleSignup(event){
  event.preventDefault()

  const name = document.getElementById("signupName").value
  const email = document.getElementById("signupEmail").value
  const password = document.getElementById("signupPass").value
  const confirm = document.getElementById("signupConfirm").value

  if(password !== confirm){
     showToast("Passwords do not match")
     return
  }
  try{

     const response = await fetch("http://localhost:5000/api/auth/signup",{

        method:"POST",
        headers:{
           "Content-Type":"application/json"
        },

        body:JSON.stringify({
           name,
           email,
           password
        })

     })

     const data = await response.json()

     if(data.token){
        localStorage.setItem("token",data.token)
        showToast("Signup successful")
        setTimeout(()=>{
           showPage("home")
        },1000)
     }else{
        showToast(data.message)
     }

  }catch(err){

     showToast("Server error")

  }

}

// ─── DARK MODE ───
function toggleDark() {
  darkMode = !darkMode;
  document.body.classList.toggle('dark', darkMode);
  document.querySelector('.dark-toggle').textContent = darkMode ? '☀️' : '🌙';
}

// ─── TOAST ───
function showToast(msg) {
  const t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(() => t.classList.remove('show'), 3000);
}

// ─── MOBILE MENU ───
function toggleMobileMenu() {
  showToast('Use the nav links to browse SEIRA 💎');
}
